481: 	for lo < hi {
482: 		ents, err := l.slice(lo, hi, pageSize)
483: 		if err != nil {
484: 			return err
485: 		} else if len(ents) == 0 {
486: 			return fmt.Errorf("got 0 entries in [%d, %d)", lo, hi)
